import re


class IperfReportParser:
    """Class for iperf report parsing"""

    def __init__(self, report_file_path):
        """
        Constructor of IperfReportParser class.

        :param report_file_path:   Path to iperf report file
        :type  report_file_path:   str
        """
        with open(report_file_path) as f:
            self.report_file = f.readlines()
            f.close()
        self.report_parsed = {"avg": None, "samples": [], "error": None}
        self._error_regex = r".*(error|failed).*"
        self._multi_sample_regex = \
            r"^\[SUM\]\s+(?P<START>\d+\.\d+)(-|-\s)(?P<END>\d+\.\d+)\s+sec.*(MBytes|GBytes|KBytes)" \
            r"\s+(?P<SAMPLE>(\d+\.\d+|\d+))\s+(?P<UNIT>Gbits\/sec|Mbits\/sec|Kbits\/sec).*"
        self._sample_regex = \
            r"^\[.*\d+\.*\]\s+(?P<START>\d+\.\d+)(-|-\s)(?P<END>\d+\.\d+)\s+sec.*(MBytes|GBytes|KBytes)" \
            r"\s+(?P<SAMPLE>(\d+\.\d+|\d+))\s+(?P<UNIT>Gbits\/sec|Mbits\/sec|Kbits\/sec).*"
        self.multi_stream_transfer = self._check_if_data_transfer_is_multi_stream()

    def parse_report(self):
        """
        Method for perform all parsing with report file.

        :return:   dictionary containing all parsed information form report file
        :rtype:    dict
        """
        for line in self.report_file:
            self._parse_tput_sample(line)
            self._parse_error(line)
        if not self.report_parsed["avg"]:
            self._get_average_tput_value_from_samples()
        return self.report_parsed

    def _check_if_data_transfer_is_multi_stream(self):
        for line in self.report_file:
            if "SUM" in line:
                return True
        else:
            return False

    def _parse_tput_sample(self, line):
        if self.multi_stream_transfer:
            sample_regex_compiled = re.search(self._multi_sample_regex, line)
        else:
            sample_regex_compiled = re.search(self._sample_regex, line)
        if sample_regex_compiled:
            sample = {"start": float(sample_regex_compiled.group("START")),
                      "end": float(sample_regex_compiled.group("END")),
                      "value": float(sample_regex_compiled.group("SAMPLE")),
                      "unit": sample_regex_compiled.group("UNIT")}
            self.report_parsed["samples"].append(sample)
            self._check_if_sample_is_avg_value(sample)

    def _parse_error(self, line):
        error_regex_compiled = re.search(self._error_regex, line)
        if error_regex_compiled:
            self.report_parsed["error"] = line

    def _check_if_sample_is_avg_value(self, sample):
        if sample["end"] - sample["start"] > 5:
            self.report_parsed["avg"] = str(sample["value"]) + sample["unit"]

    def _get_average_tput_value_from_samples(self):
        all_values = []
        for sample in self.report_parsed["samples"]:
            all_values.append(sample["value"])
        if all_values:
            self.report_parsed["avg"] = str(sum(all_values) / len(all_values)) + sample["unit"]
        else:
            raise Exception("Cannot parse iperf report content")
